// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Your Cal.com username (from cal.com/<username>/<event>)
    cal_username: "danielle-traynor-hc7i3n",
    // The event type to book (the last part of your booking link)
    event_type_slug: "30min",
    // Your time zone, e.g. America/New_York, America/Chicago, America/Los_Angeles
    timezone: "America/New_York",
    // Optional. Leave empty for a public booking page; otherwise paste a cal_live_... key
    cal_api_key: "",
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
// Function tools send Vapi's tool-call envelope; API Request tools POST the
// parameters as the whole body.
let args = toolCall.function?.arguments ?? toolCall.arguments ?? (body.message ? {} : body);
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

const cfg = $('Config').first().json;
const start = DateTime.fromISO(String(args.start_time ?? ''), { setZone: true });
const valid = start.isValid && start > DateTime.now();
const phone = String(args.caller_phone || call.customer?.number || msg.customer?.number || '').replace(/[\s().-]/g, '');
const email = String(args.email ?? '').trim().toLowerCase();
const attendee = { name: String(args.caller_name || 'New lead'), timeZone: cfg.timezone, language: 'en' };
if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) attendee.email = email;
if (/^\+[0-9]{8,15}$/.test(phone)) attendee.phoneNumber = phone;
const notes = [
  args.business_name ? `Business: ${args.business_name}` : '',
  phone ? `Phone: ${phone}` : '',
  args.notes ? `Notes: ${args.notes}` : '',
  'Booked by Billy (IntakeOps AI receptionist).',
].filter(Boolean).join('\n');
const booking = {
  start: valid ? start.toUTC().toISO() : '',
  eventTypeSlug: cfg.event_type_slug,
  username: cfg.cal_username,
  attendee,
  metadata: {
    source: 'billy',
    phone: phone.slice(0, 500),
    business: String(args.business_name ?? '').slice(0, 500),
  },
};
return [{
  json: {
    tool_call_id: toolCallId,
    valid,
    spoken_time: valid ? start.setZone(cfg.timezone).toFormat("cccc, LLLL d 'at' h:mm a") : '',
    has_email: Boolean(attendee.email),
    booking,
    booking_with_notes: { ...booking, bookingFieldsResponses: { notes } },
  },
}];

// If this booking page has no 'notes' field Cal.com rejects it; retry without.
const res = $input.first().json;
const text = JSON.stringify(res).toLowerCase();
return [{ json: { ...res, retry: res.status !== 'success' && /bookingfieldsresponses|notes/.test(text) } }];

const req = $('Parse Tool Call').first().json;
const res = $input.first().json;
const text = JSON.stringify(res).toLowerCase();
let result;
if (res.status === 'success') {
  result = `Booked for ${req.spoken_time}.` +
    (req.has_email ? " Tell the caller they'll get a confirmation email with the details." : ' Confirm the time with the caller.');
} else if (/email/.test(text) && !req.has_email) {
  result = 'The calendar needs an email address to book. Ask for their email, spell it back to confirm, ' +
    'then call bookStrategyCall again with the same start_time and the email.';
} else if (/not available|unavailable|already|taken|no available|busy/.test(text)) {
  result = 'That time was just taken. Call checkCalendar again and offer the next open times.';
} else {
  result = "Booking didn't go through. Tell the caller the team will call today to confirm a time.";
}
return [{ json: { tool_call_id: req.tool_call_id, result } }];

return [{ json: {
  tool_call_id: $('Parse Tool Call').first().json.tool_call_id,
  result: 'That time is missing or in the past. Call checkCalendar again and offer one of the open times.',
} }];
